#include <iostream>
#include <cmath>

int main() {
    int n;
    std::cout << "Masukkan bilangan bulat positif: ";
    std::cin >> n;
    bool isPrime = true;
    if (n <= 1) {
        isPrime = false;
    } else {
        for (int i = 2; i <= sqrt(n); ++i) {
            if (n % i == 0) {
                isPrime = false;
                break;
            }
        }
    }
    if (isPrime) {
        std::cout << n << " adalah bilangan prima." << std::endl;
    } else {
        std::cout << n << " bukan bilangan prima." << std::endl;
    }
    return 0;
}
